var S="2026-11-01",M="https://nssdc.gsfc.nasa.gov/planetary/factsheet/",a=(e,t,n,r,o,i,l,h,d,c,u,m,p,g,y,f,b,v,w,T,k,x)=>({id:e,name:{zh:t,en:n},type:r,color:o,diameter:i,mass:l,gravity:h,temp:d,rotation:c,period:u,au:m,tilt:p,e:g,inclination:y,moons:f,summary:b,atmosphere:v,structure:w,feature:T,satellites:k,missions:x,source:e==="sun"?"https://science.nasa.gov/sun/facts/":M,article:`https://science.nasa.gov/${e==="sun"?"sun":e==="earth"?"earth":e}/`,reviewed:S}),s=[a("sun","\u592A\u9633","Sun",["\u6052\u661F","Star"],"#ffc363",1392700,1989e27,274,5500,609.12,null,null,7.25,null,null,null,["\u592A\u9633\u5305\u542B\u592A\u9633\u7CFB\u7EDD\u5927\u90E8\u5206\u7684\u8D28\u91CF\u3002\u6838\u5FC3\u7684\u6838\u805A\u53D8\u4E0D\u65AD\u91CA\u653E\u80FD\u91CF\uFF0C\u4E3A\u5730\u7403\u63D0\u4F9B\u5149\u4E0E\u70ED\u3002","The Sun holds most of the mass in our solar system. Nuclear fusion in its core supplies the light and heat that reach Earth."],["\u5149\u7403\u4E4B\u4E0A\u662F\u8272\u7403\u4E0E\u65E5\u5195\uFF1B\u65E5\u5195\u6E29\u5EA6\u53EF\u8FDC\u9AD8\u4E8E\u5149\u7403\u3002","Above the photosphere lie the chromosphere and corona; the corona is much hotter than the photosphere."],["\u6838\u5FC3\u3001\u8F90\u5C04\u533A\u3001\u5BF9\u6D41\u533A\u3001\u5149\u7403\u3001\u8272\u7403\u548C\u65E5\u5195\u3002\u592A\u9633\u6CA1\u6709\u56FA\u4F53\u8868\u9762\u3002","Core, radiative zone, convective zone, photosphere, chromosphere and corona. There is no solid surface."],["\u592A\u9633\u7684\u4E0D\u540C\u7EAC\u5EA6\u4EE5\u4E0D\u540C\u901F\u5EA6\u81EA\u8F6C\uFF1B\u8FD9\u91CC\u7684\u81EA\u8F6C\u5468\u671F\u4E3A\u8D64\u9053\u9644\u8FD1\u7684\u53C2\u8003\u503C\u3002","The Sun rotates at different rates at different latitudes. The rotation period here is an approximate equatorial reference."],["\u592A\u9633\u6CA1\u6709\u201C\u536B\u661F\u6570\u91CF\u201D\u8FD9\u4E00\u884C\u661F\u5206\u7C7B\u6307\u6807\uFF1B\u516B\u5927\u884C\u661F\u56F4\u7ED5\u5B83\u516C\u8F6C\u3002","A planetary moon count does not apply to the Sun. The eight planets orbit it."],[["\u5E15\u514B\u592A\u9633\u63A2\u6D4B\u5668 \xB7 2018 \u5E74\u53D1\u5C04\uFF0C\u8FD1\u8DDD\u79BB\u7814\u7A76\u65E5\u5195\u4E0E\u592A\u9633\u98CE\u3002","Parker Solar Probe \xB7 launched in 2018 to study the corona and solar wind.","https://science.nasa.gov/mission/parker-solar-probe/"],["\u592A\u9633\u8F68\u9053\u5668 \xB7 2020 \u5E74\u53D1\u5C04\uFF0C\u7814\u7A76\u592A\u9633\u53CA\u5176\u65E5\u7403\u5C42\u3002","Solar Orbiter \xB7 launched in 2020 to study the Sun and heliosphere.","https://science.nasa.gov/mission/solar-orbiter/"]]),a("mercury","\u6C34\u661F","Mercury",["\u7C7B\u5730\u884C\u661F","Terrestrial planet"],"#c7bdb1",4879,33e22,3.7,167,1407.6,88,.387,.034,.206,7,0,["\u8DDD\u79BB\u592A\u9633\u6700\u8FD1\u3001\u4E5F\u662F\u516B\u5927\u884C\u661F\u4E2D\u6700\u5C0F\u7684\u4E00\u9897\u3002\u5E03\u6EE1\u649E\u51FB\u5751\u7684\u8868\u9762\u8BB0\u5F55\u4E86\u6F2B\u957F\u7684\u649E\u51FB\u5386\u53F2\u3002","The smallest planet and the closest to the Sun. Its cratered terrain records a long history of impacts."],["\u53EA\u6709\u6781\u7A00\u8584\u7684\u5916\u9038\u5C42\uFF0C\u65E0\u6CD5\u50CF\u6D53\u539A\u5927\u6C14\u90A3\u6837\u50A8\u5B58\u548C\u642C\u8FD0\u70ED\u91CF\u3002","A very thin exosphere cannot retain and redistribute heat like a dense atmosphere."],["\u91D1\u5C5E\u6838\u5FC3\u5360\u6BD4\u8F83\u5927\uFF0C\u5916\u90E8\u4E3A\u7845\u9178\u76D0\u5730\u5E54\u548C\u5730\u58F3\u3002","A relatively large metallic core beneath a silicate mantle and crust."],["\u81EA\u8F6C\u4E0E\u516C\u8F6C\u5448 3:2 \u5171\u632F\uFF1A\u6BCF\u7ED5\u592A\u9633\u4E24\u5708\uFF0C\u7EA6\u81EA\u8F6C\u4E09\u5708\u3002\u6C34\u661F\u4E0D\u662F\u6700\u70ED\u7684\u884C\u661F\u3002","A 3:2 spin\u2013orbit resonance: three rotations for every two solar orbits. Mercury is not the hottest planet."],["\u6CA1\u6709\u5DF2\u77E5\u5929\u7136\u536B\u661F\uFF0C\u4E5F\u6CA1\u6709\u884C\u661F\u73AF\u3002","No known natural moons or rings."],[["\u4FE1\u4F7F\u53F7 \xB7 2011 \u5E74\u8FDB\u5165\u6C34\u661F\u8F68\u9053\uFF0C\u7ED8\u5236\u5168\u7403\u5730\u56FE\u5E76\u7814\u7A76\u78C1\u573A\u3002","MESSENGER \xB7 entered Mercury orbit in 2011, mapping the planet and studying its magnetic field.","https://science.nasa.gov/mission/messenger/"]]),a("venus","\u91D1\u661F","Venus",["\u7C7B\u5730\u884C\u661F","Terrestrial planet"],"#e5b98a",12104,487e22,8.9,464,-5832.5,224.7,.723,177.4,.007,3.4,0,["\u5927\u5C0F\u4E0E\u5730\u7403\u63A5\u8FD1\uFF0C\u5374\u88AB\u6D53\u539A\u5927\u6C14\u5305\u56F4\u3002\u5F3A\u70C8\u6E29\u5BA4\u6548\u5E94\u8BA9\u5B83\u6210\u4E3A\u592A\u9633\u7CFB\u6700\u70ED\u7684\u884C\u661F\u3002","Similar in size to Earth but wrapped in a dense atmosphere. An intense greenhouse effect makes Venus the hottest planet."],["\u4E3B\u8981\u4E3A\u4E8C\u6C27\u5316\u78B3\uFF0C\u8986\u76D6\u786B\u9178\u4E91\uFF1B\u8868\u9762\u6C14\u538B\u7EA6\u4E3A\u5730\u7403\u6D77\u5E73\u9762\u7684 92 \u500D\u3002","Mostly carbon dioxide with sulfuric-acid clouds; surface pressure is about 92 times Earth\u2019s sea-level pressure."],["\u5CA9\u77F3\u5730\u58F3\u3001\u5730\u5E54\u548C\u91D1\u5C5E\u6838\u5FC3\uFF0C\u8868\u9762\u5177\u6709\u5E7F\u6CDB\u706B\u5C71\u5730\u8C8C\u3002","Rocky crust, mantle and metallic core, with widespread volcanic landforms."],["\u9006\u5411\u81EA\u8F6C\uFF0C\u800C\u4E14\u4E00\u6B21\u6052\u661F\u81EA\u8F6C\u6BD4\u4E00\u5E74\u7684\u516C\u8F6C\u8FD8\u957F\u3002\u753B\u9762\u663E\u793A\u7684\u662F\u4E91\u5C42\u8D34\u56FE\u3002","It rotates retrograde, and one sidereal rotation takes longer than its year. The texture shown depicts its clouds."],["\u6CA1\u6709\u5DF2\u77E5\u5929\u7136\u536B\u661F\uFF0C\u4E5F\u6CA1\u6709\u884C\u661F\u73AF\u3002","No known natural moons or rings."],[["\u9EA6\u54F2\u4F26\u53F7 \xB7 1990 \u5E74\u8FDB\u5165\u91D1\u661F\u8F68\u9053\uFF0C\u7528\u96F7\u8FBE\u7A7F\u900F\u4E91\u5C42\u7ED8\u5236\u8868\u9762\u3002","Magellan \xB7 entered orbit in 1990 and mapped the surface by radar through the clouds.","https://science.nasa.gov/mission/magellan/"]]),a("earth","\u5730\u7403","Earth",["\u7C7B\u5730\u884C\u661F","Terrestrial planet"],"#75b8e6",12756,597e22,9.8,15,23.9,365.2,1,23.4,.017,0,1,["\u6211\u4EEC\u5171\u540C\u7684\u5BB6\u56ED\uFF0C\u4E5F\u662F\u76EE\u524D\u552F\u4E00\u5DF2\u77E5\u5B58\u5728\u751F\u547D\u7684\u4E16\u754C\u3002\u6DB2\u6001\u6D77\u6D0B\u3001\u5927\u6C14\u4E0E\u5CA9\u77F3\u5708\u5171\u540C\u5851\u9020\u5B9C\u5C45\u73AF\u5883\u3002","Our shared home and the only world known to host life. Liquid oceans, atmosphere and a rocky interior shape its habitable environment."],["\u4E3B\u8981\u4E3A\u6C2E\u6C14\u548C\u6C27\u6C14\uFF0C\u6C34\u6C7D\u4E0E\u5176\u4ED6\u5FAE\u91CF\u6C14\u4F53\u53C2\u4E0E\u6C14\u5019\u8C03\u8282\u3002","Mostly nitrogen and oxygen, with water vapour and trace gases influencing the climate."],["\u5730\u58F3\u3001\u5730\u5E54\u3001\u6DB2\u6001\u5916\u6838\u548C\u56FA\u6001\u5185\u6838\uFF1B\u677F\u5757\u6784\u9020\u6301\u7EED\u6539\u53D8\u5730\u8868\u3002","Crust, mantle, liquid outer core and solid inner core; plate tectonics continually reshapes the surface."],["23.9 \u5C0F\u65F6\u662F\u76F8\u5BF9\u9065\u8FDC\u6052\u661F\u7684\u81EA\u8F6C\u5468\u671F\uFF0C\u65E5\u5E38\u4F7F\u7528\u7684\u5E73\u5747\u592A\u9633\u65E5\u7EA6\u4E3A 24 \u5C0F\u65F6\u3002","23.9 hours is the sidereal rotation period; the familiar mean solar day is about 24 hours."],["\u6708\u7403 \xB7 \u5730\u7403\u552F\u4E00\u7684\u5929\u7136\u536B\u661F\u3002\u753B\u9762\u4E2D\u7684\u6708\u7403\u8F68\u9053\u4E0E\u5C3A\u5BF8\u5355\u72EC\u653E\u5927\uFF0C\u4FBF\u4E8E\u89C2\u5BDF\u3002","The Moon \xB7 Earth\u2019s only natural satellite. Its displayed size and orbit are separately enlarged for visibility."],[["\u9646\u5730\u536B\u661F\u8BA1\u5212 \xB7 \u81EA 1972 \u5E74\u5F00\u59CB\u6301\u7EED\u8BB0\u5F55\u5730\u8868\u53D8\u5316\u3002","Landsat \xB7 observing changes to Earth\u2019s land surface since 1972.","https://science.nasa.gov/mission/landsat/"]]),a("mars","\u706B\u661F","Mars",["\u7C7B\u5730\u884C\u661F","Terrestrial planet"],"#df8c6d",6792,642e21,3.7,-65,24.6,687,1.524,25.2,.094,1.8,2,["\u94C1\u6C27\u5316\u7269\u8BA9\u706B\u661F\u5448\u73B0\u7EA2\u8272\u3002\u53E4\u8001\u6CB3\u9053\u3001\u4E09\u89D2\u6D32\u4E0E\u77FF\u7269\u8BC1\u636E\u8BF4\u660E\uFF0C\u5B83\u7684\u8FC7\u53BB\u66FE\u6709\u6DB2\u6001\u6C34\u6D3B\u52A8\u3002","Iron oxides give Mars its red colour. Ancient channels, deltas and minerals preserve evidence of liquid water in its past."],["\u7A00\u8584\u5927\u6C14\u4E3B\u8981\u4E3A\u4E8C\u6C27\u5316\u78B3\uFF0C\u96BE\u4EE5\u7EF4\u6301\u7A33\u5B9A\u7684\u5730\u8868\u6DB2\u6001\u6C34\u3002","A thin, mostly carbon-dioxide atmosphere makes stable liquid water at the surface difficult."],["\u5CA9\u77F3\u5730\u58F3\u4E0E\u5730\u5E54\u5305\u56F4\u91D1\u5C5E\u6838\u5FC3\uFF0C\u62E5\u6709\u5927\u578B\u706B\u5C71\u4E0E\u5CE1\u8C37\u7CFB\u7EDF\u3002","A rocky crust and mantle surround a metallic core, with enormous volcanoes and canyon systems."],["\u5965\u6797\u5E15\u65AF\u5C71\u4E0E\u6C34\u624B\u5CE1\u8C37\u5C55\u793A\u4E86\u8FD9\u9897\u884C\u661F\u5DE8\u5927\u7684\u5730\u5F62\u8D77\u4F0F\u3002\u706B\u661F\u81EA\u8F6C\u5468\u671F\u63A5\u8FD1\u5730\u7403\u3002","Olympus Mons and Valles Marineris reveal its dramatic topography. Mars rotates on a timescale close to Earth\u2019s."],["\u706B\u536B\u4E00\u4E0E\u706B\u536B\u4E8C \xB7 \u4E24\u9897\u5F62\u72B6\u4E0D\u89C4\u5219\u7684\u5C0F\u536B\u661F\u3002","Phobos and Deimos \xB7 two small, irregular moons."],[["\u6BC5\u529B\u53F7 \xB7 2021 \u5E74\u767B\u9646\u6770\u6CFD\u7F57\u9668\u77F3\u5751\uFF0C\u7814\u7A76\u53E4\u73AF\u5883\u5E76\u91C7\u96C6\u5CA9\u77F3\u6837\u672C\u3002","Perseverance \xB7 landed in Jezero crater in 2021 to study ancient environments and collect rock samples.","https://science.nasa.gov/mission/mars-2020-perseverance/"]]),a("jupiter","\u6728\u661F","Jupiter",["\u6C14\u6001\u5DE8\u884C\u661F","Gas giant"],"#d8b498",142984,1898e24,23.1,-110,9.9,4331,5.204,3.1,.049,1.3,95,["\u592A\u9633\u7CFB\u6700\u5927\u7684\u884C\u661F\uFF0C\u5177\u6709\u6761\u5E26\u72B6\u4E91\u5C42\u3001\u5F3A\u78C1\u573A\u548C\u5DE8\u5927\u7684\u98CE\u66B4\u3002\u5927\u7EA2\u6591\u662F\u5176\u4E2D\u6700\u8457\u540D\u7684\u5929\u6C14\u7CFB\u7EDF\u3002","The largest planet has banded clouds, a powerful magnetic field and immense storms, including the Great Red Spot."],["\u4E3B\u8981\u4E3A\u6C22\u4E0E\u6C26\uFF0C\u4E91\u5C42\u4E2D\u7684\u4E0D\u540C\u5316\u5408\u7269\u5F62\u6210\u5C42\u6B21\u548C\u989C\u8272\u3002","Mostly hydrogen and helium, with cloud compounds creating layers and colours."],["\u6C14\u4F53\u5411\u6DF1\u5904\u9010\u6E10\u53D8\u4E3A\u9AD8\u538B\u6D41\u4F53\uFF0C\u53EF\u80FD\u5B58\u5728\u5F25\u6563\u6838\u5FC3\uFF1B\u6CA1\u6709\u53EF\u7AD9\u7ACB\u7684\u56FA\u4F53\u8868\u9762\u3002","Gas grades into high-pressure fluids at depth, with evidence for a diffuse core. There is no solid surface to stand on."],["\u7EA6 10 \u5C0F\u65F6\u5B8C\u6210\u4E00\u6B21\u81EA\u8F6C\uFF0C\u5FEB\u901F\u81EA\u8F6C\u4F7F\u8D64\u9053\u9F13\u8D77\u3002\u6728\u661F\u4E5F\u6709\u6697\u6DE1\u7684\u884C\u661F\u73AF\u3002","A roughly ten-hour rotation contributes to its equatorial bulge. Jupiter also has faint rings."],["\u6728\u536B\u4E00\u3001\u6728\u536B\u4E8C\u3001\u6728\u536B\u4E09\u3001\u6728\u536B\u56DB \xB7 \u56DB\u9897\u4F3D\u5229\u7565\u536B\u661F\u3002\u6728\u536B\u4E09\u662F\u592A\u9633\u7CFB\u6700\u5927\u7684\u536B\u661F\u3002","Io, Europa, Ganymede and Callisto \xB7 the four Galilean moons. Ganymede is the largest moon in the solar system."],[["\u6731\u8BFA\u53F7 \xB7 2016 \u5E74\u8FDB\u5165\u6728\u661F\u8F68\u9053\uFF0C\u7814\u7A76\u5185\u90E8\u7ED3\u6784\u3001\u5927\u6C14\u548C\u78C1\u573A\u3002","Juno \xB7 entered Jupiter orbit in 2016 to study its interior, atmosphere and magnetic field.","https://science.nasa.gov/mission/juno/"]]),a("saturn","\u571F\u661F","Saturn",["\u6C14\u6001\u5DE8\u884C\u661F","Gas giant"],"#dfc693",120536,568e24,9,-140,10.7,10747,9.572,26.7,.052,2.5,274,["\u4EE5\u5BBD\u9614\u660E\u4EAE\u7684\u884C\u661F\u73AF\u95FB\u540D\u3002\u73AF\u5E76\u4E0D\u662F\u5B8C\u6574\u7684\u56FA\u4F53\u5706\u76D8\uFF0C\u800C\u7531\u5927\u91CF\u51B0\u7C92\u4E0E\u5CA9\u77F3\u788E\u5C51\u7EC4\u6210\u3002","Famous for its broad, bright rings, which are made of countless icy particles and rocky fragments rather than a solid disk."],["\u4E3B\u8981\u4E3A\u6C22\u4E0E\u6C26\uFF0C\u5927\u6C14\u4E2D\u6709\u4E91\u5E26\u3001\u98CE\u66B4\u548C\u9AD8\u901F\u6C14\u6D41\u3002","Mostly hydrogen and helium, with cloud bands, storms and fast winds."],["\u5185\u90E8\u538B\u529B\u4F7F\u7269\u8D28\u9010\u6E10\u6210\u4E3A\u9AD8\u5BC6\u5EA6\u6D41\u4F53\uFF0C\u6DF1\u5904\u5177\u6709\u91CD\u5143\u7D20\u5BCC\u96C6\u533A\u57DF\u3002","Increasing pressure produces dense fluids, with a deep region enriched in heavy elements."],["\u5E73\u5747\u5BC6\u5EA6\u4F4E\u4E8E\u6C34\uFF1B\u8FD9\u662F\u7269\u8D28\u5E73\u5747\u5BC6\u5EA6\u7684\u6BD4\u8F83\uFF0C\u5E76\u4E0D\u610F\u5473\u7740\u5B58\u5728\u80FD\u88C5\u4E0B\u571F\u661F\u7684\u6D77\u6D0B\u3002","Its mean density is lower than water\u2019s. This is a density comparison, not a claim that a real ocean could hold Saturn."],["\u571F\u536B\u516D\u5177\u6709\u6D53\u539A\u5927\u6C14\uFF1B\u571F\u536B\u4E8C\u7684\u5357\u6781\u55B7\u6D41\u4E3A\u5730\u4E0B\u6D77\u6D0B\u63D0\u4F9B\u7EBF\u7D22\u3002","Titan has a thick atmosphere; Enceladus\u2019s south-polar plumes provide evidence for a subsurface ocean."],[["\u5361\u897F\u5C3C\u2014\u60E0\u66F4\u65AF \xB7 \u7814\u7A76\u571F\u661F\u7CFB\u7EDF\uFF0C\u60E0\u66F4\u65AF\u63A2\u6D4B\u5668\u4E8E 2005 \u5E74\u767B\u9646\u571F\u536B\u516D\u3002","Cassini\u2013Huygens \xB7 explored the Saturn system; Huygens landed on Titan in 2005.","https://science.nasa.gov/mission/cassini/"]]),a("uranus","\u5929\u738B\u661F","Uranus",["\u51B0\u5DE8\u884C\u661F","Ice giant"],"#9bd6df",51118,868e23,8.7,-195,-17.2,30589,19.16,97.8,.047,.8,28,["\u81EA\u8F6C\u8F74\u51E0\u4E4E\u8EBA\u5728\u8F68\u9053\u5E73\u9762\u5185\uFF0C\u4EFF\u4F5B\u4FA7\u8EBA\u7740\u7ED5\u592A\u9633\u8FD0\u884C\u3002\u5927\u6C14\u4E2D\u7684\u7532\u70F7\u5438\u6536\u7EA2\u5149\uFF0C\u5F62\u6210\u84DD\u7EFF\u8272\u5916\u89C2\u3002","Its rotation axis lies almost in its orbital plane, so it appears to roll around the Sun. Atmospheric methane absorbs red light."],["\u6C22\u3001\u6C26\u548C\u7532\u70F7\u6784\u6210\u5916\u5C42\u5927\u6C14\u3002","Hydrogen, helium and methane make up the outer atmosphere."],["\u5916\u5C42\u6C14\u4F53\u4E4B\u4E0B\u5BCC\u542B\u6C34\u3001\u6C28\u548C\u7532\u70F7\u7B49\u9AD8\u538B\u7269\u8D28\uFF1B\u201C\u51B0\u5DE8\u661F\u201D\u4E0D\u4EE3\u8868\u5B83\u662F\u51B0\u51BB\u7684\u5B9E\u5FC3\u7403\u3002","Below the gas are high-pressure materials rich in water, ammonia and methane. \u201CIce giant\u201D does not mean a frozen solid sphere."],["\u7EA6 98\xB0 \u7684\u8F74\u503E\u89D2\u9020\u6210\u6781\u7AEF\u5B63\u8282\u53D8\u5316\uFF1B\u5B83\u4E5F\u62E5\u6709\u8F83\u6697\u7684\u73AF\u7CFB\u7EDF\u3002","An axial tilt near 98\xB0 creates extreme seasons. It also has a dark ring system."],["\u5929\u536B\u4E09\u3001\u5929\u536B\u56DB\u3001\u5929\u536B\u4E00\u3001\u5929\u536B\u4E8C\u4E0E\u5929\u536B\u4E94\u662F\u4E3B\u8981\u536B\u661F\u3002","Titania, Oberon, Ariel, Umbriel and Miranda are major moons."],[["\u65C5\u884C\u8005 2 \u53F7 \xB7 1986 \u5E74\u98DE\u63A0\u5929\u738B\u661F\uFF0C\u63D0\u4F9B\u8FD1\u8DDD\u79BB\u5F71\u50CF\u4E0E\u6D4B\u91CF\u3002","Voyager 2 \xB7 flew past Uranus in 1986, returning close-up images and measurements.","https://science.nasa.gov/mission/voyager/"]]),a("neptune","\u6D77\u738B\u661F","Neptune",["\u51B0\u5DE8\u884C\u661F","Ice giant"],"#799fe4",49528,102e24,11,-200,16.1,59800,30.18,28.3,.01,1.8,16,["\u8DDD\u79BB\u592A\u9633\u6700\u8FDC\u7684\u516B\u5927\u884C\u661F\u6210\u5458\u3002\u5BD2\u51B7\u7684\u5927\u6C14\u4ECD\u6709\u5F3A\u70C8\u98CE\u66B4\u548C\u9AD8\u901F\u98CE\u3002","The most distant of the eight planets. Its cold atmosphere nevertheless hosts powerful storms and fast winds."],["\u4E3B\u8981\u4E3A\u6C22\u3001\u6C26\u53CA\u7532\u70F7\u3002\u5E38\u89C1\u7684\u6DF1\u84DD\u8272\u7167\u7247\u53EF\u80FD\u7ECF\u8FC7\u989C\u8272\u589E\u5F3A\u3002","Mostly hydrogen, helium and methane. Familiar deep-blue images may have enhanced colour."],["\u5CA9\u77F3\u6838\u5FC3\u5916\u5305\u88F9\u5BCC\u542B\u6C34\u3001\u6C28\u4E0E\u7532\u70F7\u7684\u9AD8\u538B\u7269\u8D28\uFF0C\u518D\u5411\u5916\u8FC7\u6E21\u5230\u6C14\u4F53\u3002","A rocky core is surrounded by high-pressure water-, ammonia- and methane-rich material, grading outward into gas."],["\u4E00\u6B21\u516C\u8F6C\u7EA6\u9700 165 \u4E2A\u5730\u7403\u5E74\u3002\u8D34\u56FE\u662F\u5386\u53F2\u5F71\u50CF\u7684\u793A\u610F\u8868\u8FBE\uFF0C\u5E76\u975E\u5F53\u524D\u5929\u6C14\u3002","One orbit takes about 165 Earth years. The texture illustrates historical imagery, not current weather."],["\u6D77\u536B\u4E00 \xB7 \u4EE5\u9006\u884C\u8F68\u9053\u7ED5\u6D77\u738B\u661F\u8FD0\u884C\uFF0C\u53EF\u80FD\u662F\u88AB\u6355\u83B7\u7684\u5929\u4F53\u3002","Triton \xB7 travels in a retrograde orbit and may be a captured object."],[["\u65C5\u884C\u8005 2 \u53F7 \xB7 1989 \u5E74\u98DE\u63A0\u6D77\u738B\u661F\u53CA\u6D77\u536B\u4E00\u3002","Voyager 2 \xB7 flew past Neptune and Triton in 1989.","https://science.nasa.gov/mission/voyager/"]])],A=Object.fromEntries(s.map(e=>[e.id,e])),E=s.filter(e=>e.id!=="sun"),I=(e,t)=>Array.isArray(e)?e[t==="en"?1:0]:e?.[t]??e;function G(e,t){return e.diameter/t.diameter}export{S as a,M as b,s as c,A as d,E as e,I as f,G as g};
